import React from "react";
import _ from "lodash";
import TitleBar from "../components/TitleBar";
import doublePendulumImg from "../assets/images/double-pendulum/headliner.png";
import reedSolomonImg from "../assets/images/reed-solomon/headliner.png";
import Grid from "@material-ui/core/Grid";
import ProjectBar from "../components/ProjectBar";
import "../assets/css/projects.css";

function Projects(props) {
  const projects = {
    doublePendulum: {
      path: "/double-pendulum",
      description: "double pendulum learning simulation",
      blurb:
        "Built in April of 2018, watch carts attempt to balance poles on top of themselves, and when they fail, learn from their mistakes. Utilizing a genetic evolution algorithm called NEAT, the carts learn to balance!",
      image: doublePendulumImg,
      srcName: "double-pendulum"
    },
    reedSolomon: {
      path: "/reed-solomon",
      description: "reed-solomon encoding/decoding",
      blurb:
        "Built in December of 2018, learn about how a message can be garbled and messed with to guarantee that if the data were to get corrupted in transmission, the original message would still be recoverable!",
      image: reedSolomonImg,
      srcName: "reed-solomon"
    }
  };

  const srcToImageMap = new Map();
  srcToImageMap.set("double-pendulum", doublePendulumRegular);
  srcToImageMap.set("reed-solomon", reedSolomonRegular);
  srcToImageMap.set("double-pendulum_hover", doublePendulumHover);
  srcToImageMap.set("reed-solomon_hover", reedSolomonHover);

  const getCurrentProjectView = () => {
    const el = document.querySelector(".carousel-item.active");
    if (el) {
      return el.getAttribute("project-name");
    }
  };

  const imgMouseEnter = e => {
    document.getElementById(
      getCurrentProjectView() + "-image"
    ).src = srcToImageMap.get(getCurrentProjectView() + "_hover");
  };

  const imgMouseOut = e => {
    document.getElementById(
      getCurrentProjectView() + "-image"
    ).src = srcToImageMap.get(getCurrentProjectView());
  };

  return (
    <div>
      <TitleBar title="projects" />
      <Grid
        container
        direction="column"
        justify="center"
        alignItems="center"
        className="project-bars-wrapper"
      >
        {_.map(projects, project => (
          <ProjectBar
            image={srcToImageMap.get(project.srcName)}
            title={project.description}
            path={project.path}
            blurb={project.blurb}
          />
        ))}
      </Grid>
      {/*       
      <div
        className="carouselWrapper carouselImgWrapper"
        onMouseOver={imgMouseEnter}
        onMouseOut={imgMouseOut}
      >
        <Carousel indicators={true}>
          {_.map(projects, project => (
            <Carousel.Item
              project-name={project.srcName}
              key={project.srcName}
              href={project.path}
            >
              <a href={project.path}>
                <img
                  className="d-block w-100"
                  id={`${project.srcName}-image`}
                  src={srcToImageMap.get(project.srcName)}
                  alt={`Project "${project.srcName}"`}
                />
                <Carousel.Caption>
                  <h5 className="description">{project.description}</h5>
                </Carousel.Caption>
              </a>
            </Carousel.Item>
          ))}
        </Carousel>
      </div> */}
    </div>
  );
}

export default Projects;
